#include "GLTFParser.h"
#include <rapidjson/document.h>
bool GLTFParser::Parse(const std::string&json){meshes.clear();materials.clear();rapidjson::Document d;d.Parse(json.c_str());if(d.HasParseError()||!d.IsObject())return false;if(d.HasMember("meshes")&&d["meshes"].IsArray())for(const auto&m:d["meshes"].GetArray())meshes.push_back(m.IsObject()&&m.HasMember("name")&&m["name"].IsString()?m["name"].GetString():"mesh");if(d.HasMember("materials")&&d["materials"].IsArray())for(const auto&m:d["materials"].GetArray())materials.push_back(m.IsObject()&&m.HasMember("name")&&m["name"].IsString()?m["name"].GetString():"material");return d.HasMember("asset")&&d["asset"].IsObject();}
std::vector<std::string> GLTFParser::GetMeshes()const{return meshes;} std::vector<std::string> GLTFParser::GetMaterials()const{return materials;}